const { getDefaultConfig } = require('expo/metro-config');
const { withNativeWind } = require('nativewind/metro');

// Expo auto-configures pnpm monorepos (watchFolders / nodeModulesPaths) since SDK 52.
const config = getDefaultConfig(__dirname);

// Token CSS is generated by @tadriss/ui-tokens (`pnpm tokens:build`).
module.exports = withNativeWind(config, {
  input: require.resolve('@tadriss/ui-tokens/mobile.css'),
});
